def d(n):
    """Calculates the number of divisors of n."""
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

def check_k(k):
    """Checks if d(2k^3) == 2k."""
    lhs = d(2 * k**3)
    rhs = 2 * k
    return lhs == rhs

solutions = [1, 4, 10]
for k in solutions:
    print(f"k={k}: LHS=d(2*{k}**3)={d(2 * k**3)}, RHS=2*{k}. Match: {check_k(k)}")
